package com.rustraid.service
import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat;import com.google.firebase.database.*
class FirebaseMonitorService:Service(){override fun onStartCommand(i:Intent?,f:Int,id:Int):Int{val n=getSystemService(NotificationManager::class.java);n.createNotificationChannel(NotificationChannel("monitor","Raid monitoring",NotificationManager.IMPORTANCE_LOW));startForeground(8,NotificationCompat.Builder(this,"monitor").setSmallIcon(android.R.drawable.ic_popup_sync).setContentTitle("Rust Raid Alarm").setContentText("Monitoring Firebase").build());FirebaseDatabase.getInstance().getReference("raid_alarm/alarm_active").addValueEventListener(object:ValueEventListener{override fun onDataChange(s:DataSnapshot){if(s.getValue(Boolean::class.java)==true)startService(AlarmService.intent(this@FirebaseMonitorService))};override fun onCancelled(e:DatabaseError){}});return START_STICKY};override fun onBind(i:Intent?)=null}
